window.T8 = window.T8 || [];
T8.push(
{id:"m1",n:"1-mavzu",t:"Iftixorimsan – jannatmakon O‘zbekiston!",b:1,
 map:{c:"Jannatmakon O‘zbekiston",br:[
  {t:"Vatan tuyg‘usi",e:"🏡",k:["kindik qoni","ona va Vatan","yuksak jasorat"],x:"Inson ulg‘aygan sari o‘z Vatanida kerakligini, uning bir bo‘lagi ekanini his qiladi va Vatanini onasidek yaxshi ko‘radi."},
  {t:"Haqiqiy vatanparvar",e:"🛡️",k:["shaxsiy daxldorlik","el-yurt ravnaqi","faollik"],x:"Donishmand: vatanparvar — Vatan qudrati, el-yurt ravnaqi va yosh avlod kamoloti yo‘lida shaxsiy daxldorlikni his etgan, faol inson."},
  {t:"Yoshlik fasli",e:"🌸",k:["bahor fasli","imkoniyat","mas’ullik"],x:"Yoshlik bahor fasliga o‘xshaydi. Berilgan imkoniyatdan unumli foydalanib, salohiyatini oshirgan yoshlarning kelajagi go‘zal bo‘ladi."},
  {t:"Ma’naviy meros",e:"📜",k:["omonat","durdona asarlar","ezgu fazilatlar"],x:"Ajdodlardan qolgan ma’naviy meros avlodlarga omonat. Unda yurt qadri, inson fazilati va ezgu umr haqida aytilgan."},
  {t:"Baxtli hayot sirlari",e:"🔑",k:["tinchlik va ravnaq","e’tiqod va sog‘liq","totuv oila"],x:"Fozil inson baxt sirlarini besh iboraga jamladi: yurtda tinchlik va ravnaq, e’tiqod va sog‘liq, kasb-hunar va bilim, totuv oila, farzandlar kamoli."}]},
 q:[
 {t:"m",q:"Donishmand fikricha, haqiqiy vatanparvar qanday inson?",a:["Yurt ravnaqiga shaxsiy daxldorlikni his etib, faol bo‘lgan","Yurt haqida chiroyli so‘zlab, chetda kuzatib turadigan","Faqat o‘z oilasi farovonligini o‘ylab mehnat qiladigan","Faqat bayram kunlarida Vatanni eslab, madh etadigan"],e:"Vatan qudrati, el-yurt ravnaqi va yosh avlod kamoloti yo‘lida shaxsiy daxldorlikni his etgan, faol inson."},
 {t:"m",q:"Darslikda yoshlik qaysi faslga o‘xshatiladi?",a:["Bahorga","Yozga","Kuzga","Qishga"],e:"Yoshlik — porloq kelajak uchun tinimsiz harakat qilinadigan, o‘z ifori va chiroyini yo‘qotmagan bahor fasli kabi."},
 {t:"m",q:"Vatanni sevish imondan ekanini aytgan donishmand jannatga nima bilan erishilishini ta’kidlagan?",a:["Onaning roziligi bilan","Boylik to‘plash bilan","Uzoq safar qilish bilan","Mansabga erishish bilan"],e:"«Jannat onalar oyog‘i ostida», unga onaning roziligi bilan erishiladi. Shuning uchun Vatan onaga qiyoslanadi."},
 {t:"m",q:"«Kimki yurtni sevmasa, u hech kim va hech nimani sevmaydi» hikmati kimniki?",a:["Mahmud Zamaxshariy","Abdulla Avloniy","Alisher Navoiy","Abu Rayhon Beruniy"],e:"Bu Mahmud Zamaxshariyning ma’naviyat xazinasidan keltirilgan hikmati."},
 {t:"m",q:"Ajdodlardan qolgan ma’naviy meros biz avlodlar uchun nima hisoblanadi?",a:["Omonat","Ermak","Ortiqcha yuk","Tasodif"],e:"Darslikda: ma’naviy meros biz avlodlarga omonat hisoblanadi."},
 {t:"m",q:"Qadimdan ota-bobolarimiz nimani har narsadan ustun qo‘yganlar?",a:["Vatan va millat manfaati, or-nomusini","Shaxsiy boylik va hovli-joy kengligini","O‘zining shon-shuhrati va mansabini","O‘yin-kulgi va dam olish vaqtini"],e:"Ota-bobolarimiz Vatan, millat manfaati, or-nomusi, qadr-qimmatini har narsadan ustun qo‘yganlar."},
 {t:"m",q:"Qaysi ma’rifatparvar yoshlarni asarlari orqali Vatanga sadoqatli bo‘lib kamol topishga undagan?",a:["Abdulla Avloniy","Pavel Durov","Konfutsiy","Rene Dekart"],e:"Abdulla Avloniy asarlarida vatanparvarlik va insonparvarlik g‘oyalarini ilgari surgan."},
 {t:"m",q:"Fozil insonning baxtli hayot haqidagi beshta iborasiga qaysi biri kiradi?",a:["Foydali kasb-hunar va bilim","Katta boylik va hashamat","Yuksak mansab va hokimiyat","Uzoq safar va sarguzasht"],e:"Besh ibora ichida «foydali kasb-hunar va bilim» bor."},
 {t:"tf",q:"Vatanga muhabbat darslikda muqaddas tuyg‘u deb ataladi.",a:true,e:"«Vatanga muhabbat tuyg‘usi muqaddasdir», deyiladi."},
 {t:"tf",q:"Fozil inson baxtli yashash sirlarini oxiri qalin kitobga aylantirib, ko‘paytirdi.",a:false,e:"Aksincha, u yozganlarini qisqartirib, oxiri besh iboraga jamladi."},
 {t:"tf",q:"Yoshlarning kelajagi butun bir millatning shirin tashvishi deb ta’riflanadi.",a:true,e:"Darslikdagi matnda aynan shunday fikr aytilgan."},
 {t:"f",q:"Nima uchun Vatan onaga qiyoslanadi? O‘z fikringizni 2 ta dalil bilan yozing.",e:"Masalan: Vatan ham ona kabi qadrli va yagona; uni sevib, ko‘z qorachig‘idek ardoqlash unga munosib farzand bo‘lishni anglatadi."}]},

{id:"m2",n:"2-mavzu",t:"Millatlararo hamjihatlik",b:1,
 map:{c:"Millatlararo hamjihatlik",br:[
  {t:"Bag‘rikenglik",e:"🤝",k:["ahil yashash","bir diyor farzandlari","teng huquq"],x:"O‘zbek, qoraqalpoq, rus, qozoq yoki boshqa millat vakili bo‘lsin — barchasi bir diyor farzandlari."},
  {t:"Dinlar totuvligi",e:"🕊️",k:["16 ta konfessiya","an’analar","sharoit"],x:"Respublikamizda 16 ta diniy konfessiya vakillari ahil-inoq yashaydi; ularga an’analarini bajarish uchun sharoit yaratiladi."},
  {t:"Davlat siyosati",e:"🏛️",k:["ustuvor yo‘nalish","teng imkoniyat","vatanparvarlik"],x:"Millatlararo hamjihatlik va fuqarolar totuvligini mustahkamlash davlat siyosatining muhim ustuvor yo‘nalishlaridan biri."},
  {t:"Markaz va jamiyatlar",e:"🌍",k:["138 ta markaz","36 ta jamiyat","do‘stlik aloqalari"],x:"138 ta milliy madaniy markaz urf-odatlarni asraydi; 36 ta do‘stlik jamiyati xorijiy davlatlar bilan aloqalarni rivojlantiradi."},
  {t:"Eng katta boylik",e:"💎",k:["totuvlik","o‘zaro ishonch","yagona Vatan"],x:"Eng katta boyligimiz — millatlararo totuvlik va hamjihatlik. U do‘stlikka asoslanadi, ishonch va mehr-oqibatni yuzaga keltiradi."}]},
 q:[
 {t:"m",q:"Darslikka ko‘ra, O‘zbekistonda nechta diniy konfessiya vakillari ahil yashaydi?",a:["16 ta","6 ta","36 ta","138 ta"],e:"Respublikamizda 16 ta diniy konfessiya vakillari ahil-inoq yashamoqda."},
 {t:"m",q:"Darslikdagi ma’lumotga ko‘ra, yurtimizda nechta milliy madaniy markaz faoliyat ko‘rsatadi?",a:["138 ta","16 ta","36 ta","83 ta"],e:"Yurtimizda 138 ta milliy madaniy markaz faoliyat ko‘rsatmoqda."},
 {t:"m",q:"36 ta do‘stlik jamiyatining vazifalaridan biri qaysi?",a:["Xorijiy davlatlar bilan do‘stlik aloqalarini rivojlantirish","Chet ellik sayyohlardan soliq va bojlarni yig‘ib borish","Maktablarda sport musobaqalariga hakamlik qilib turish","Harbiy xizmatchilarni orden va medallar bilan taqdirlash"],e:"Jamiyatlar do‘stlik aloqalarini rivojlantiradi va mamlakatning ijobiy imijini targ‘ib etadi."},
 {t:"m",q:"Darslikda bizning eng katta boyligimiz nima deb ataladi?",a:["Millatlararo totuvlik va hamjihatlik","Yer osti boyliklari va oltin konlari","Ko‘p qavatli binolar va keng yo‘llar","Savdo-sotiqdan keladigan katta daromad"],e:"Eng katta boyligimiz — jamiyatda hukm surayotgan millatlararo totuvlik va hamjihatlik."},
 {t:"m",q:"Millatlarning o‘zaro totuvligi va hamjihatligi nimaga asoslanadi?",a:["Do‘stlikka","Raqobatga","Majburlashga","Befarqlikka"],e:"Darslikda: totuvlik va hamjihatlik do‘stlikka asoslanadi."},
 {t:"m",q:"Millatlar orasida birlik yo‘qolib, nifoq va adovat hukm surishi inqirozga olib kelishini kim ta’kidlagan?",a:["Abdulla Avloniy","Viktor Pak","Berdaq","Tomas Edison"],e:"Avloniy bunday qavmning inqirozga yuz tutganligi tarix sahifalaridan ma’lumligini yozgan."},
 {t:"m",q:"Davlat siyosatiga ko‘ra, barcha fuqarolarga nimadan qat’i nazar teng huquq va imkoniyat yaratiladi?",a:["Millati va diniy e’tiqodidan","Yoshi va bo‘yining balandligidan","Kiyinish didi va qiziqishidan","Sportdagi natijalari va vaznidan"],e:"Barcha fuqarolarga millati va diniy e’tiqodidan qat’i nazar teng huquq va imkoniyatlar yaratiladi."},
 {t:"m",q:"Darslikka ko‘ra, milliy hamjihatlikni ta’minlashning asosiy omili nima?",a:["Yagona Vatan tuyg‘usini mustahkamlab, yagona maqsad sari yo‘naltirish","Har bir millatning manfaatini boshqalarnikidan qat’iy ajratib qo‘yish","Millatlarni bir-biri bilan imkon qadar kam muloqot qildirish","Faqat bitta millatning urf-odatlarini barcha uchun majburiy qilish"],e:"Barcha millat va elatlarda yagona Vatan tuyg‘usini mustahkamlash va manfaatlarni uyg‘unlashtirish asosiy omildir."},
 {t:"tf",q:"Yurtimizda yashayotgan turli millat vakillari bir diyorning farzandlari hisoblanadi.",a:true,e:"Millatidan qat’i nazar barchasi bir diyor farzandlari."},
 {t:"tf",q:"Darslikka ko‘ra, tinchlik va xotirjamlikni asrash faqat kattalarning ishi, yoshlar bunga hissa qo‘shmaydi.",a:false,e:"Aksincha, yoshlar ham tinchlikni asrashga o‘z hissasini qo‘shishi lozim."},
 {t:"tf",q:"Milliy madaniy markazlar yosh avlodni millatlararo bag‘rikenglik ruhida tarbiyalashga hissa qo‘shadi.",a:true,e:"Markazlar qadriyat va an’analarni asraydi hamda yoshlarni bag‘rikenglikda tarbiyalaydi."},
 {t:"f",q:"Bag‘rikeng inson bo‘lish uchun nima qilish kerak? Misol keltiring.",e:"Masalan: boshqa millat va din vakillarining qadriyatlarini hurmat qilish, ahil va do‘stona munosabatda bo‘lish."}]},

{id:"m3",n:"3-mavzu",t:"Har bir farzand – Vatan himoyachisi",b:1,
 map:{c:"Vatan himoyachisi",br:[
  {t:"Barkamol avlod",e:"💪",k:["jismoniy tarbiya","mehnat","toza havo"],x:"Jismoniy tarbiya, aqliy va jismoniy mehnat, ertalabki sayr yoshlarni kuchli, mehnatsevar va mustaqil fikrli qiladi."},
  {t:"Sharafli vazifa",e:"🎖️",k:["Vatan himoyasi","qutlug‘ ne’mat","muqaddas tuproq"],x:"Sharafli vazifalar ichida Vatanni himoya qilish eng sharaflisidir. Vatan — insonga ato etilgan eng qutlug‘ ne’mat."},
  {t:"Jasorat namunasi",e:"⚔️",k:["Jaloliddin Manguberdi","Amir Temur","orden"],x:"1999-yilda Jaloliddin Manguberdining 800 yilligi nishonlandi, 2000-yilda uning nomidagi orden ta’sis etildi."},
  {t:"To‘rt burch",e:"📋",k:["o‘zi va oilasi","davlat","o‘zga odamlar"],x:"Insonning burchi to‘rtga bo‘linadi: o‘z oldidagi, oilasi, davlat va boshqa odamlar oldidagi burch."},
  {t:"Daxldorlik",e:"🙋",k:["mas’uliyat","faol fuqarolik","fidoyilik"],x:"Fuqarolar jamiyat oldidagi mas’uliyat va burchni his qilgan joyda daxldorlik va faol fuqarolik kuchli bo‘ladi."}]},
 q:[
 {t:"m",q:"Darslikka ko‘ra, sharafli vazifalar ichida eng sharaflisi qaysi?",a:["O‘z Vatanini himoya qilish","Katta boylik to‘plash","Mashhur bo‘lishga erishish","Ko‘p mamlakatga sayohat qilish"],e:"Dunyoda sharafli vazifalar ko‘p, ammo Vatanni himoya qilish sharaflilar ichra sharaflisidir."},
 {t:"m",q:"Jaloliddin Manguberdi tavalludining 800 yilligi qaysi yilda nishonlandi?",a:["1999-yilda","1991-yilda","2000-yilda","2003-yilda"],e:"1999-yil yurtimizda 800 yillik keng nishonlandi."},
 {t:"m",q:"«Jaloliddin Manguberdi» ordeni qachon ta’sis etilgan?",a:["2000-yil 30-avgustda","1999-yil 1-sentabrda","2003-yil 9-mayda","1992-yil 8-dekabrda"],e:"Orden 2000-yil 30-avgust kuni ta’sis etilgan."},
 {t:"m",q:"2003-yilda «Jaloliddin Manguberdi» ordeni bilan qaysi hudud mukofotlangan?",a:["Xorazm viloyati","Samarqand viloyati","Buxoro viloyati","Namangan viloyati"],e:"2003-yili shu orden bilan Xorazm viloyati mukofotlangan."},
 {t:"m",q:"Darslikda insonning burchlari nechta turga bo‘linadi?",a:["To‘rtga","Ikkiga","Uchga","Yettiga"],e:"O‘z oldidagi, oilasi, davlat va o‘zga odamlar oldidagi burch."},
 {t:"m",q:"«Har bir odam haqiqiy baxtga erishishi uchun shaxsiy manfaatini xalq manfaati bilan birlashtirishi kerak» degan fikr kimniki?",a:["Berdaq","Mahmud Zamaxshariy","Konfutsiy","Pifagor"],e:"Bu shoir Berdaqning so‘zlari."},
 {t:"m",q:"Haqiqiy vatanparvar hayot yo‘lini qaysi illatlardan yiroq tutadi?",a:["Riyokorlik, tamagirlik, yolg‘onchilik","Mehnatsevarlik, kamtarlik, rostgo‘ylik","Mardlik, oliyjanoblik, beg‘arazlik","Qat’iyat, matonat, mushohadakorlik"],e:"U riyokorlik, tamagirlik va yolg‘onchilikdan uzoq yuradi."},
 {t:"m",q:"Konstitutsiyaga ko‘ra, Vatan mudofaasi va xavfsizligiga kim mas’ul?",a:["Qurolli Kuchlar","Mahalla qo‘mitalari","Sport jamiyatlari","Savdo tashkilotlari"],e:"Darslikdagi savolda Konstitutsiyada mudofaa va xavfsizlikka Qurolli Kuchlar mas’ulligi ta’kidlangani aytiladi."},
 {t:"tf",q:"Muntazam jismoniy tarbiya va mehnat yoshlarning mustaqil fikrlashi charxlanishiga ham yordam beradi.",a:true,e:"Bunday yoshlar jismonan kuchli bo‘ladi, mustaqil fikrlashi teranlashadi."},
 {t:"tf",q:"Minhojiddin Mirzo fikricha, inson ma’naviy qudrati uning Vatan oldidagi burchini anglashiga umuman bog‘liq emas.",a:false,e:"Aksincha, ma’naviy olam kuchi Vatan oldidagi burch va mas’uliyatni anglashda ham namoyon bo‘ladi."},
 {t:"tf",q:"Jaloliddin Manguberdi ordeni Vatan himoyasida jasorat ko‘rsatgan qo‘mondonlik tarkibidagi harbiylarga beriladi.",a:true,e:"Orden yuksak harbiy mahorat va jasorat ko‘rsatgan qo‘mondonlik tarkibiga kiruvchi harbiylarga beriladi."},
 {t:"f",q:"Siz hozir o‘quvchi sifatida Vatan himoyasiga qanday tayyorlana olasiz?",e:"Masalan: sog‘liqni mustahkamlash, sport bilan shug‘ullanish, bilim olish, iroda va intizomni tarbiyalash, qoidalarga rioya qilish."}]},

{id:"m4",n:"4-mavzu",t:"Hayotda o‘z istaklarimizni anglash",b:2,
 map:{c:"Istaklarni anglash",br:[
  {t:"Xohishlar",e:"💭",k:["son-sanoqsiz","aniq ko‘rish","kelajak"],x:"Xohishlar juda ko‘p. Ularni aniq ko‘ra olsak, yaxshi istaklarga erishish mumkin. Xohishlar hozir va ertaga kim bo‘lishimizni belgilaydi."},
  {t:"Kelajakni tasavvur",e:"🔭",k:["20 yildan keyin","uy va kasb","oila"],x:"Xohishlarni anglashning eng yaxshi yo‘li — o‘zingizni kelajakda tasavvur qilish."},
  {t:"Maqsad bosqichlari",e:"🪜",k:["aniq bayon","reja","birinchi qadam"],x:"Maqsadni aniq bayon qilish, harakat rejasini tuzish, qadam qo‘yish va o‘zgarishlarga e’tibor berish kerak."},
  {t:"Ibratli hayot",e:"🏅",k:["Suyima G‘aniyeva","Akmal Saidov","tirishqoqlik"],x:"Navoiyshunos Suyima G‘aniyeva va akademik Akmal Saidov tinimsiz mehnat bilan yuksak natijalarga erishgan."},
  {t:"Foydali natija",e:"🌟",k:["ijobiy orzu","oqibatni o‘ylash","ziyonsizlik"],x:"Maqsad oqibatini oldindan o‘ylash, natija o‘zingizga ham, boshqalarga ham foyda keltirishi kerak."}]},
 q:[
 {t:"m",q:"Darslikka ko‘ra, xohishlarni anglashning eng yaxshi yo‘li qaysi?",a:["O‘zini kelajakda tasavvur qilish","Do‘stlar istagini takrorlash","Barcha ishni keyinga surish","Faqat bugungi kunni o‘ylash"],e:"«Xohishlarni anglashning eng yaxshi yo‘li o‘zingizni kelajakda tasavvur qilishdir»."},
 {t:"m",q:"Bizning hozir kimligimiz va ertaga kim bo‘lishimizni nima belgilab beradi?",a:["Xohishlarimiz","Kiyimlarimiz","Tasodiflar","Ob-havo"],e:"Kelajagimiz xohishlarimizga bog‘liq."},
 {t:"m",q:"Jamiki yaxshi istaklarga qachon erishish mumkin?",a:["Ularni aniq ko‘ra olsak","Ularni hammadan yashirsak","Ularni tez-tez almashtirsak","Omadni jim kutib tursak"],e:"Yaxshi istaklarga ularni aniq ko‘ra olsak erishish mumkin."},
 {t:"m",q:"Suyima G‘aniyeva qaysi sohada o‘ziga xos ilmiy maktab yaratgan?",a:["Navoiyshunoslik","Astronomiya","Iqtisodiyot","Tibbiyot"],e:"U navoiyshunoslik sohasida ilmiy maktab yaratgan."},
 {t:"m",q:"Talaba Akmalga bobosi qanday o‘git bergan edi?",a:["Behuda o‘tgan vaqtning uvoli bor","Boylik hamma narsadan ustun turadi","Ko‘p uxlagan odam kuchli bo‘ladi","Kitobdan ko‘ra o‘yin foydaliroqdir"],e:"«Har bir behuda o‘tgan vaqtning uvoli bor, uvol bo‘lgan umrni ortga qaytarib bo‘lmaydi»."},
 {t:"m",q:"Akmal Saidov Toshkent davlat universitetining qaysi fakultetini qizil diplom bilan tugatgan?",a:["Yuridik","Tarix","Fizika","Filologiya"],e:"U hozirgi O‘zbekiston Milliy universitetining Yuridik fakultetini tugatgan."},
 {t:"m",q:"«Dunyoni tartibga solishga urinma, eng avval o‘z istaklaringni boshqara bil» fikri kimniki?",a:["Rene Dekart","Benedikt Spinoza","Fransua Volter","Blez Paskal"],e:"Bu Rene Dekart hikmati."},
 {t:"m",q:"Maqsadni bosqichma-bosqich belgilashda qaysi qadam birinchi turadi?",a:["Maqsadni aniq bayon qilish","Natijani bayram qilib o‘tkazish","Boshqalardan natija kutib turish","O‘zgarishlarni oxirida baholash"],e:"Avval maqsad aniq bayon qilinadi, so‘ng harakatlar rejasi tuziladi."},
 {t:"tf",q:"Darslikka ko‘ra, har bir inson o‘z xohishlarini doim aniq ko‘ra oladi.",a:false,e:"Bu oson bo‘lib ko‘rinsa-da, har kim ham xohishlarini aniq ko‘ra olmaydi."},
 {t:"tf",q:"Erishiladigan maqsad boshqa odamlarga ziyon yetkazmasligi haqida o‘ylash kerak.",a:true,e:"Natija o‘zingizga ham, boshqalarga ham faqat foyda keltirishi kerak."},
 {t:"tf",q:"Sevimli mashg‘ulotingiz orqali siz muvaffaqiyatga qisman allaqachon erishgan bo‘lasiz.",a:true,e:"Darslik: sevimli mashg‘ulot orqali 10 foizga bo‘lsa ham muvaffaqiyatga erishgansiz."},
 {t:"f",q:"Bitta maqsadingizni yozing: unga erishish uchun ishni nimadan boshlaysiz va nimadan voz kechasiz?",e:"Javobda aniq maqsad, imkoniyat, birinchi qadam, voz kechiladigan narsa va kerakli yordam ko‘rsatilsin."}]},

{id:"m5",n:"5-mavzu",t:"Qat’iy fe’l-atvorning muhimligi",b:2,
 map:{c:"Qat’iy fe’l-atvor",br:[
  {t:"Maqsad sharti",e:"🎯",k:["qattiq xohish","iroda","mas’uliyat"],x:"Qattiq xohish, mustahkam e’tiqod, qat’iy iroda, mas’uliyat va oliy maqsad bilan astoydil harakat qilgan inson maqsadiga erishadi."},
  {t:"Mustahkam poydevor",e:"🗼",k:["Minorai Kalon","47,5 metr","asos"],x:"Minorai Kalon mustahkam poydevori tufayli asrlar osha turibdi. Inson umri va muvaffaqiyatining asosi — fe’l-atvor."},
  {t:"Ishda ahamiyati",e:"💼",k:["Harvard","85 foiz","15 foiz"],x:"Harvard tadqiqotiga ko‘ra, ishga kirish va yuksalishda fe’l-atvor o‘rni 85 foiz, bilim va tajribaniki 15 foiz."},
  {t:"Jahlni jilovlash",e:"🥋",k:["Aziz va Bahrom","bosiqlik","uzr"],x:"Taekvandochi Aziz haqoratga musht bilan javob bermadi. Bobosi: kuchli odam — jahlini jilovlay olgan odam."},
  {t:"Shijoat",e:"🔥",k:["tirishqoqlik","g‘ayrat","vaqtdan foydalanish"],x:"Tirishqoqlik va g‘ayrat orzularga quvvat beradi, yashirin imkoniyatlarni ro‘yobga chiqaradi."}]},
 q:[
 {t:"m",q:"Harvard universiteti tadqiqotiga ko‘ra, ishga kirish va mavqe ko‘tarilishida fe’l-atvorning o‘rni qancha?",a:["85 foiz","15 foiz","50 foiz","5 foiz"],e:"Fe’l-atvor 85 foiz, bilim va tajriba 15 foiz o‘rin tutadi."},
 {t:"m",q:"Minorai Kalonning balandligi qancha?",a:["47,5 metr","11,5 metr","74,5 metr","25,5 metr"],e:"Balandligi 47,5 metr, asosi esa 11,5 metr chuqurlikda."},
 {t:"m",q:"Inson umri va muvaffaqiyatining minoralar asosiga o‘xshatilgan tayanchi nima?",a:["Fe’l-atvor","Boylik","Tashqi ko‘rinish","Omad"],e:"Inson umrining, muvaffaqiyatining ham tag zamini bor — bu fe’l-atvor."},
 {t:"m",q:"Azizning bobosi fikricha, kuchli odam kim?",a:["Jahli chiqqanda o‘zini yenga olgan","Hamma raqiblarini yiqita olgan","Eng baland ovozda gapira olgan","Eng ko‘p medal yig‘a olgan"],e:"Kuchli odam hammani yenggan emas, jahlini jilovlay olgan odamdir."},
 {t:"m",q:"Aziz sportning qaysi turi bo‘yicha Osiyo chempioni bo‘lgan?",a:["Taekvando","Boks","Kurash","Dzyudo"],e:"Aziz taekvando bo‘yicha Osiyo chempioni edi."},
 {t:"m",q:"Azizning bosiq muomalasini eslagan Bahrom nima qildi?",a:["Uyalib, undan uzr so‘radi","Yana ham qattiqroq baqirdi","Ustozga undan shikoyat qildi","U bilan gaplashmaydigan bo‘ldi"],e:"Bahrom qilmishidan uyalib, «Uzr so‘rayman, og‘ayni», dedi."},
 {t:"m",q:"«Yaxshi fe’l-atvor bilan yashagan inson o‘zini yomon qiliqlardan saqlaydi» hikmati kimniki?",a:["Ahmad Yugnakiy","O‘tkir Hoshimov","Jaloliddin Rumiy","Najmiddin Kubro"],e:"Bu Ahmad Yugnakiy so‘zlari."},
 {t:"m",q:"Darslikka ko‘ra, shijoatli va intiluvchan insonlarda qaysi ishtiyoq kuchli bo‘ladi?",a:["Vaqtdan unumli foydalanish","Ishni ertaga qoldirish","Bahslashib vaqt o‘tkazish","Mo‘jizani jim kutib turish"],e:"Shijoatli insonlarda vaqtdan unumli foydalanishga ishtiyoq kuchli."},
 {t:"tf",q:"Minorai Kalonning asosi yer sathidan 11,5 metr chuqurlikda joylashgan.",a:true,e:"Mustahkam poydevor minoraning asrlar osha turishiga sabab."},
 {t:"tf",q:"Konfutsiy so‘zingizga vafo qilmaslikni va ishda qat’iyatsiz bo‘lishni maslahat bergan.",a:false,e:"Aksincha: «So‘zingizga vafo qiling, ishda qat’iyatli bo‘ling»."},
 {t:"tf",q:"Qattiq xohish, iroda, mas’uliyat va oliy maqsad bilan astoydil harakat qilgan inson maqsadiga erisha oladi.",a:true,e:"Darslikda aynan shunday ta’kidlanadi."},
 {t:"f",q:"Muvaffaqiyat uchun o‘zingizda qaysi 2 ta fazilatni shakllantirmoqchisiz va nega?",e:"Masalan: sabr-matonat va qat’iyat — qiyinchilikda to‘xtab qolmaslikka yordam beradi."}]},

{id:"m6",n:"6-mavzu",t:"Qiyin vaziyatda hissiyotlarni boshqarish",b:2,
 map:{c:"Hissiyotlarni boshqarish",br:[
  {t:"Hissiyot — quvvat",e:"⚡",k:["ichki kuch","to‘g‘ri yo‘naltirish","tashabbus"],x:"Hissiyot — quvvat. To‘g‘ri yo‘naltirilsa yutuq yaratadi, noto‘g‘ri ishlatilsa buzg‘unchilik va yo‘qotishga olib keladi."},
  {t:"Irodali shoir",e:"✒️",k:["«O‘zbegim»","5 yil ishsizlik","«Faust»"],x:"Erkin Vohidov «O‘zbegim» qasidasi tufayli tazyiqqa uchradi, ammo irodasi sinmay «Faust»ni tarjima qildi."},
  {t:"G‘azab xavfi",e:"🌋",k:["qon bosimi","yurak-qon tomir","jilovlash"],x:"G‘azab eng xavfli hissiyot: salomatlikka zarar yetkazadi. Uni jilovlash baxtiyorlik va o‘ziga ishonchni oshiradi."},
  {t:"Boshqarish yo‘llari",e:"🧘",k:["darhol javob bermaslik","chuqur nafas","ijobiy javob"],x:"Darhol munosabat bildirmang, chuqur nafas oling, o‘zingizni o‘rganing, ijobiy munosabat bilan javob qaytaring."},
  {t:"Hissiyot turlari",e:"🎭",k:["ijobiy","salbiy","aralash"],x:"His-tuyg‘ular ijobiy (quvonch, baxt), salbiy (qayg‘u, umidsizlik) va aralash bo‘ladi."}]},
 q:[
 {t:"m",q:"Erkin Vohidov qaysi asari tufayli tazyiqqa uchrab, 5 yil ishsiz qolgan?",a:["«O‘zbegim» qasidasi","«Inson» qasidasi","«Faust» tarjimasi","«Saydana» asari"],e:"1968-yilda yozilgan «O‘zbegim» qasidasida milliy faxr yoritilgani sabab bo‘lgan."},
 {t:"m",q:"Ishsiz yurgan yillarida Erkin Vohidov qaysi asarni o‘zbek tiliga tarjima qildi?",a:["Gyotening «Faust» asarini","«Robinzon Kruzo» romanini","«Mufassal» qo‘llanmasini","«Avesto» kitobini"],e:"U bo‘sh yurganidan foydalanib, «Faust»ni tarjima qildi."},
 {t:"m",q:"Darslikda eng xavfli hissiyot sifatida qaysi biri ko‘rsatilgan?",a:["G‘azab","Quvonch","Shukronalik","Hamdardlik"],e:"G‘azab hayot va salomatlikka zarar yetkazadi, baxtsizlikka olib keladi."},
 {t:"m",q:"Salbiy hissiyotni boshqarishda birinchi maslahat qanday?",a:["Darhol munosabat bildirmaslik","Darhol qattiq javob qaytarish","Hammaga arz qilib chiqish","O‘sha zahoti qaror chiqarish"],e:"Avval chuqur nafas olib, bu o‘tkinchi ekanini o‘zingizga uqtiring."},
 {t:"m",q:"Boshqarilgan xavotir insonni nimaga undaydi?",a:["Muammoga yechim izlashga","Hafsalasizlikka berilishga","Yolg‘izlanib qolishga","Boshqalarni ayblashga"],e:"Boshqarilmagan xavotir hafsalasizlikka olib keladi, boshqarilgani yechim izlashga undaydi."},
 {t:"m",q:"Darslikka ko‘ra, boshqarilgan hasad odamni nimaga majbur qiladi?",a:["O‘z ustida ko‘proq ishlashga","Boshqalarga ziyon yetkazishga","Ishni butunlay tashlab qo‘yishga","Do‘stlaridan uzoqlashishga"],e:"Boshqarilmagan hasad hasadchini kuydiradi, boshqarilgani o‘z ustida ishlashga majbur qiladi."},
 {t:"m",q:"Quyidagilardan qaysi biri ijobiy his-tuyg‘ularga misol?",a:["Quvonch, baxt, sevgi","Qayg‘u, umidsizlik","G‘azab, nafrat","Qo‘rquv, yo‘qotish hissi"],e:"Ijobiy: quvonch, baxt, sevgi."},
 {t:"m",q:"Yaxshi kayfiyatni saqlash uchun darslik nimani tavsiya qiladi?",a:["Hazil qilish va sevimli mashg‘ulot bilan band bo‘lish","Salbiy fikrlarni uzoq vaqt davomida takrorlab yurish","Hech narsa bilan shug‘ullanmay yolg‘iz o‘tirib olish","Jahl chiqqanda birovlarga baland ovozda gapirish"],e:"Musiqa mashqlari, salbiy fikrlardan qochish, hazil va sevimli mashg‘ulot yordam beradi."},
 {t:"tf",q:"G‘azab yurak-qon tomir va qon bosimi bilan bog‘liq kasalliklarga sabab bo‘lishi mumkin.",a:true,e:"Ovqat hazm qilish bilan bog‘liq kasalliklar ham paydo bo‘ladi."},
 {t:"tf",q:"Oshkor qilinmagan hissiyot hech qachon qayta namoyon bo‘lmaydi.",a:false,e:"U qalbga tirik ko‘milgan harakatga o‘xshaydi — bir kuni bo‘y ko‘rsatadi."},
 {t:"tf",q:"O‘tkir Hoshimov o‘z ildizini inkor qilgan daraxt qurib qolishini yozgan.",a:true,e:"Nuqul o‘tmishidan noliydigan odam kelajagini barbod qilishi mumkin."},
 {t:"f",q:"Jahlingiz chiqqanda o‘zingizni qanday tinchlantirasiz? Mavzudagi maslahatlardan foydalaning.",e:"Masalan: darhol javob bermaslik, chuqur nafas olish, yaxshi voqeani eslash, ijobiy javob qaytarish."}]},

{id:"m7",n:"7-mavzu",t:"Hayot – ulug‘ ne’mat",b:2,
 map:{c:"Hayot — omonat",br:[
  {t:"Qadrli omonat",e:"🎁",k:["imkoniyat","xiyonat qoralanadi","barcha dinlar"],x:"Hayot — insonga berilgan eng qadrli omonat va imkoniyat. Bu omonatga xiyonat barcha dinlarda qoralanadi."},
  {t:"Giyohvandlik",e:"⛔",k:["qabih yo‘l","200 mingdan ortiq","yomonliklar boshi"],x:"Qiyinchilikka sabri yetmagan ba’zilar qabih yo‘lni tanlaydi. Giyohvandlikdan har yili 200 mingdan ortiq odam o‘ladi."},
  {t:"Hayot daftari",e:"📖",k:["haqiqat va razolat","o‘ziga ishonch","qat’iyat"],x:"Hayot sinov va quvonchlardan iborat; ularni munosib yengish uchun o‘ziga ishonch va qat’iyat kerak."},
  {t:"U M R",e:"⏳",k:["umid","mas’uliyat","riyozat"],x:"Umid — munosib yashashga ahd; mas’uliyat — uni sharaf bilan ado etish; riyozat — o‘z o‘rnini topish uchun harakat."},
  {t:"Intilish",e:"🚀",k:["tirishqoqlik","tole","Rumiy"],x:"«Intilganga tole yor», «Baxt yalqovga begona». Rumiy: mashaqqat chekkan xazina topadi."}]},
 q:[
 {t:"m",q:"Darslikda hayot inson uchun berilgan nima deb ataladi?",a:["Eng qadrli omonat va imkoniyat","Oddiy tasodif va o‘yin-kulgi","Faqat sinovsiz dam olish davri","Istalgancha sarflanadigan mulk"],e:"Hayot — eng qadrli omonat va imkoniyatdir."},
 {t:"m",q:"Darslik qabihlikning eng yirik ko‘rinishi deb nimani aytadi?",a:["Giyohvandlikni","Shoshqaloqlikni","Qiziqqonlikni","Parishonlikni"],e:"Qabihlikning eng yirik ko‘rinishi — giyohvandlik."},
 {t:"m",q:"Statistikaga ko‘ra, giyohvandlik oqibatida har yili qancha odam hayotdan ko‘z yumadi?",a:["200 mingdan ortiq","2 mingga yaqin","20 mingga yaqin","20 milliondan ortiq"],e:"Darslikda 200 mingdan ortiq deb ko‘rsatilgan."},
 {t:"m",q:"«UMR» so‘zi izohida «U» harfi nimani bildiradi?",a:["Umid","Uyqu","Ulfat","Uzr"],e:"Umid — hayotni munosib, baxtli yashab o‘tishga ahd qilmoq."},
 {t:"m",q:"«UMR» izohida «R» — riyozat nimani anglatadi?",a:["Hayotda o‘z o‘rnini topish uchun harakat qilish","Hayotdagi barcha mas’uliyatdan chetda turish","Qiyinchilik kelganda taslim bo‘lib qolish","Vaqtni faqat ko‘ngilochar ishlarga sarflash"],e:"Riyozat — hayotda o‘z o‘rnini topish uchun harakat qilmoq."},
 {t:"m",q:"«Kim mashaqqat chekdi – topdi g‘azna ham, kim tirishqoq bo‘ldi – ko‘p topdi karam» satrlari kimniki?",a:["Jaloliddin Rumiy","Ahmad Yugnakiy","Berdaq","Alisher Navoiy"],e:"Bu Jaloliddin Rumiy hikmati."},
 {t:"m",q:"Hayot sinovlarini munosib yengish uchun odamda nima bo‘lishi lozim?",a:["O‘ziga ishonch va qat’iyat","Loqaydlik va beparvolik","Munofiqlik va riyokorlik","Tushkunlik va umidsizlik"],e:"Sinovlarni yengishda o‘ziga ishonch va qat’iyat kerak."},
 {t:"m",q:"Xalq maqolini to‘ldiring: «Intilganga ... yor».",a:["tole","uyqu","g‘am","kibr"],e:"«Intilganga tole yor», «Baxt yalqovga begona»."},
 {t:"tf",q:"Hayot omonatiga xiyonat qilish barcha dinlarda qoralanadi.",a:true,e:"Darslikda aynan shunday ta’kidlangan."},
 {t:"tf",q:"Giyohvandlik barcha yomonliklarning boshi deb ta’riflanadi.",a:true,e:"«Giyohvandlik – barcha yomonliklarning boshidir»."},
 {t:"tf",q:"«UMR» izohiga ko‘ra, mas’uliyat — hayot yuklagan vazifadan qochishdir.",a:false,e:"Aksincha, uni zimmaga olib, sharaf bilan ado etishdir."},
 {t:"f",q:"Hayot omonatiga xiyonat qilmaslik uchun nima qilish kerak?",e:"Masalan: zararli odatlardan saqlanish, maqsad qo‘yib mehnat qilish, vaqtni behuda sarflamaslik, sinovlarga sabr qilish."}]},

{id:"m8",n:"8-mavzu",t:"Tushkunlik va besaranjomlikni boshqarish",b:3,
 map:{c:"Tushkunlikni yengish",br:[
  {t:"Otabek sinovi",e:"🍅",k:["issiqxona","bo‘ron","ona dalda"],x:"Bo‘ron issiqxonaga zarar yetkazdi. Onasi haj uchun yig‘gan pulini berib, «faqat oldinga intil», dedi."},
  {t:"Malika xulosasi",e:"🥈",k:["kumush medal","shoshqaloqlik","yangi maqsad"],x:"Malika bir vergul xatosi bilan kumush oldi, tushkunlikdan so‘ng keyingi yili g‘olib bo‘lishga ahd qildi."},
  {t:"Reja va maqsad",e:"🗺️",k:["xotirjamlik","imkoniyat","oldinga intilish"],x:"Xotirjamlikni yo‘qotmang, qobiliyat va imkoniyatni chamalang, maqsad qo‘yib, unga yo‘l chizing."},
  {t:"Muammolar yechimi",e:"🧩",k:["tafakkur","sabr-toqat","tanqidiy ko‘z"],x:"Muammolar doim bo‘ladi; ularni tafakkur, sabr va o‘z harakatiga tanqidiy qarash bilan hal qilish mumkin."},
  {t:"Tuya hikoyati",e:"🐪",k:["quduq","tuproq","yuqoriga"],x:"Quduqqa tushgan tuya ustiga tashlangan tuproqni silkib, oyog‘i ostiga olib chiqib ketdi. Muammo yuksalishga vosita bo‘lishi mumkin."}]},
 q:[
 {t:"m",q:"Otabekning issiqxonasiga nima katta zarar yetkazdi?",a:["Kuchli bo‘ron va shamol","Qattiq qishki sovuq","Toshqin suvi","Yong‘in"],e:"Bahor oxirida to‘satdan kelgan bo‘ron issiqxonalarga zarar yetkazdi."},
 {t:"m",q:"Onasi Otabekka qaysi pulni berdi?",a:["Haj ziyorati uchun yig‘ganini","Uy qurish uchun olgan qarzini","To‘y uchun sotgan molining pulini","Otasining oxirgi oylik maoshini"],e:"Otabek: «Ona, bu haj ziyoratiga deb yig‘ib qo‘ygan pullaringiz-ku?»"},
 {t:"m",q:"Pul olgach, Otabek eng birinchi maqsadi nima ekanini aytdi?",a:["Onasini hajga yuborish","Yangi mashina olish","Boshqa shaharga ko‘chish","Issiqxonani sotib yuborish"],e:"Ishlari yurishgach, onasini hajga yuborishga va’da berdi."},
 {t:"m",q:"Malika xalqaro matematiklar tanlovida qanday natijaga erishdi?",a:["Kumush medal oldi","Oltin medal oldi","Bronza medal oldi","Medalsiz qaytdi"],e:"Malika kumush medal sohibi bo‘ldi."},
 {t:"m",q:"Malikaning misol natijasiga ta’sir qilgan xatosi nima edi?",a:["Bitta vergul","Noto‘g‘ri mavzu","Bo‘sh qolgan varaq","Kech kelish"],e:"Hammasi to‘g‘ri ketayotgan edi, bitta vergul natijaga ta’sir qildi — shoshqaloqlik oqibati."},
 {t:"m",q:"Aeroportda Malika birinchi bo‘lib nima dedi?",a:["Keyingi yili albatta g‘olib bo‘lishini","Endi matematikani tashlab qo‘yishini","Hakamlar adolatsiz bo‘lganini","Boshqa tanlovga bormasligini"],e:"«Men albatta keyingi yili g‘olib bo‘laman. Oltin medalni O‘zbekistonga olib kelaman!»"},
 {t:"m",q:"Tuya hikoyatida tuya quduqdan qanday chiqdi?",a:["Tashlangan tuproqni oyoq ostiga olib, yuqoriga ko‘tarildi","Xo‘jayini qo‘shnilari yordamida arqon bilan tortib oldi","Quduq suvga to‘lgach, suzib yuqoriga chiqib oldi","Quduq devoridagi zinapoyadan sekin ko‘tarildi"],e:"Tuya ustiga tushgan tuproqni silkib tushirib, ustiga chiqib bordi."},
 {t:"m",q:"Qiyin vaziyatdan chiqish bo‘yicha qaysi maslahat darslikka mos?",a:["Har bir qarorning maqsadga ta’sirini o‘ylab ko‘rish","Birinchi kelgan fikrga ko‘ra shoshib qaror qilish","Muammo paydo bo‘lsa, undan butunlay qochib ketish","O‘z harakatlariga hech qachon baho bermaslik"],e:"Har bir qarorning maqsadga erishishdagi ahamiyatini o‘ylash lozim."},
 {t:"tf",q:"Darslikka ko‘ra, insonda muammolar doimo bo‘ladi, ularga yechim topishda tafakkurni ishga solish kerak.",a:true,e:"Muhimi — uddaburonlik va tafakkur bilan yechim topish."},
 {t:"tf",q:"Otabekning onasi unga ortga qarab, o‘tgan zararni uzoq qayg‘urishni maslahat berdi.",a:false,e:"U «faqat oldinga intil, ortga qarama», dedi."},
 {t:"tf",q:"Tuya hikoyatidan xulosa: qiyinchilik kelajakda yuqoriroq darajaga ko‘tarilishga yordam berishi mumkin.",a:true,e:"Muammo — otilgan tosh; shu toshlar yordamida yuksalish mumkin."},
 {t:"f",q:"Tushkunlikka tushgan do‘stingizga 3 ta maslahat yozing.",e:"Masalan: xotirjam bo‘l, imkoniyatingni chamala, reja tuz, sabrli bo‘l, xatodan xulosa chiqarib oldinga intil."}]},

{id:"m9",n:"9-mavzu",t:"Mashaqqatlarni yengib o‘tish",b:3,
 map:{c:"Mashaqqatlarni yengish",br:[
  {t:"Pavel Durov",e:"📱",k:["Telegram","sodda turmush","yaratuvchanlik"],x:"Durov sodda yashaydi, mol-dunyo o‘tkinchi, hayotning bosh ehtiyoji — yaratuvchanlik deb biladi."},
  {t:"Pul quli bo‘lmaslik",e:"⛓️",k:["badnafslik","isrofgarchilik","erkinlik"],x:"Pulning quliga aylanib qolish — o‘z hayotiga egalik qila olmaslikdir."},
  {t:"Pochtachi saroyi",e:"🏰",k:["Ferdinand Sheval","33 yil","qat’iyat"],x:"Fransiyalik pochtachi Sheval atrofdagilar masxarasiga qaramay, o‘zi orzu qilgan toshsaroyni qurdi."},
  {t:"Xalqlar mo‘jizasi",e:"🌏",k:["Yaponiya","Janubiy Koreya","iroda"],x:"Tabiiy resurslari deyarli yo‘q Yaponiya va Koreya xalqlar irodasi va fe’l-atvori bilan rivojlandi."},
  {t:"Mehnat hikmati",e:"🛠️",k:["Edison","10 va 90 foiz","ijodkorlik"],x:"Edison: ixtirochilikning 10 foizi tasavvur, 90 foizi mashaqqatli mehnat."}]},
 q:[
 {t:"m",q:"Pavel Durov hayotning bosh ehtiyoji nima ekanini aytadi?",a:["Yaratuvchanlik","Mol-dunyo","Hashamat","Shon-shuhrat"],e:"U mol-dunyo o‘tkinchi, bosh ehtiyoj — yaratuvchanlik deydi."},
 {t:"m",q:"Pavel Durov qaysi messenjer bilan bog‘liq loyihaning asoschisi?",a:["Telegram","Wikipedia","Skype","Gmail"],e:"Durov — Telegram va Vkontakte asoschisi."},
 {t:"m",q:"Durov fikricha, pulning quliga aylanib qolish nimani anglatadi?",a:["O‘z hayotiga egalik qila olmaslikni","Barcha orzularga tez erishishni","Chinakam erkinlikka chiqishni","Do‘stlar bilan yaqinlashishni"],e:"Pul quli o‘z hayotiga egalik qila olmaydi."},
 {t:"m",q:"Orzusidagi saroyni qurgan Ferdinand Sheval kim bo‘lib ishlagan?",a:["Pochtachi","Me’mor","Haykaltarosh","Muhandis"],e:"Savodsiz pochtachi toshlar yig‘ib saroy qurgan."},
 {t:"m",q:"Sheval o‘z saroyini necha yil davomida qurib bitkazdi?",a:["33 yil","3 yil","13 yil","43 yil"],e:"U 1879-yilda boshlab, 1912-yilda — 33 yilda tugatdi. 43 — boshlagandagi yoshi."},
 {t:"m",q:"«Ixtirochilikning 10 foizi tasavvur bo‘lsa, 90 foizi mashaqqatli mehnatdir» so‘zlari kimniki?",a:["Tomas Edison","Pavel Durov","Albert Eynshteyn","Mark Tven"],e:"Bu Tomas Edison hikmati."},
 {t:"m",q:"Yaponiya va Janubiy Koreya taraqqiyotining asosi sifatida nima ko‘rsatiladi?",a:["Xalqning ichki dunyosi, irodasi va fe’l-atvori","Juda boy tabiiy xomashyo va mineral resurslar","Katta hududi va bepoyon unumdor yerlari","Tasodifiy omad va tashqaridan kelgan boylik"],e:"Resurslari deyarli yo‘q bo‘lsa-da, xalq irodasi ularni rivojlangan davlatga aylantirdi."},
 {t:"m",q:"«Tabiiy boyliklarimiz cheklangan, biroq ijodkorligimizning chegarasi yo‘q» — bu qaysi kompaniya shiori?",a:["Posco","Telegram","Webster","Papa Johns"],e:"Janubiy Koreyaning Posco kompaniyasi shiori."},
 {t:"tf",q:"Pavel Durovning shaxsiy samolyoti va hashamatli saroyi borligi matnda ta’kidlanadi.",a:false,e:"Aksincha, unda samolyot ham, saroy ham yo‘q; sodda yashaydi."},
 {t:"tf",q:"Atrofdagilar savodsiz pochtachining saroy qurish qarorini masxara qilishgan.",a:true,e:"Shunga qaramay, Sheval ishini davom ettirdi."},
 {t:"tf",q:"Darslikka ko‘ra, mustahkam iroda va imon-e’tiqod mashaqqatni yengish uchun asosdir.",a:true,e:"Bu fazilatlar inson salohiyatini ro‘yobga chiqarishga zamin yaratadi."},
 {t:"f",q:"Sheval hayotidan qanday saboq oldingiz? Uni o‘z hayotingizga bog‘lang.",e:"Kuchli xohish, qat’iyat va tinimsiz mehnat bilan masxara va qiyinchilikka qaramay orzuga erishish mumkin."}]},

{id:"m10",n:"10-mavzu",t:"Tanqid va tanqidiy fikrlashning muhimligi",b:3,
 map:{c:"Tanqidiy fikrlash",br:[
  {t:"Nega kerak",e:"🧠",k:["bilim va xotira","muammo yechimi","ko‘nikma"],x:"Ko‘p bilim va kuchli xotira ham tanqidiy fikrlashsiz ayrim muammolarni hal qilishga yetmaydi."},
  {t:"Tekshirish",e:"🔍",k:["aniqlik","baholash","manbalar"],x:"Ma’lumot aniqligini o‘rganish, tekshirish, baholash va ishonchli manbalarga tayanish kerak."},
  {t:"Shubhali so‘zlar",e:"❓",k:["menimcha","nazarimda","balki"],x:"Suhbatdosh «menimcha», «balki» desa, axborot unchalik ishonchli emas — savol berib aniqlang."},
  {t:"Mustaqil qaror",e:"⚖️",k:["tahlil","asoslar","xulosa"],x:"Ma’lumotni tahlil qilish, shubha ostiga olish, asoslarini tekshirish va mustaqil qaror chiqarish zarur."},
  {t:"Himoya va g‘oya",e:"💡",k:["firibga qarshi","yangi g‘oya","nuqtayi nazar"],x:"Tanqidiy fikrlovchi yolg‘onchilikka qarshi immunitetga ega, o‘z fikrini himoya qiladi va yangi g‘oya beradi."}]},
 q:[
 {t:"m",q:"Suhbatdosh qaysi so‘zlarni ishlatsa, axborotni tekshirish lozim?",a:["«Menimcha», «nazarimda», «balki»","«Rahmat», «marhamat», «iltimos»","«Salom», «xayr», «ko‘rishguncha»","«Ertalab», «tushda», «kechqurun»"],e:"Bu so‘zlar axborot unchalik ishonchli emasligini bildiradi."},
 {t:"m",q:"Ishonchli bo‘lmagan axborotga duch kelganda darslik nimani tavsiya qiladi?",a:["Savol berib, aniqlik kiritishni","Darhol hammaga tarqatishni","So‘zsiz rost deb qabul qilishni","Suhbatdoshni haqorat qilishni"],e:"Bunday vaziyatda savol berib axborotga aniqlik kiritish zarur."},
 {t:"m",q:"Ko‘p ma’lumot va kuchli xotira bo‘lsa ham, ba’zi muammolarni hal qilishga qaysi ko‘nikma yetishmasligi mumkin?",a:["Tanqidiy fikrlash","Chiroyli yozish","Tez yugurish","Baland ovozda o‘qish"],e:"Tanqidiy fikrlash ko‘nikmasi bo‘lmasa, bilim yetarli bo‘lmaydi."},
 {t:"m",q:"Qaysi biri tanqidiy fikrlash belgisi?",a:["Ma’lumot aniqligini tekshirib, baholay olish","Eshitilgan har qanday gapga darrov ishonish","Tasdiqlanmagan taxminni dalil deb bilish","O‘zgalar fikrini ko‘r-ko‘rona takrorlash"],e:"Aniqlikni o‘rganish, tekshirish va baholash — tanqidiy fikrlash belgisi."},
 {t:"m",q:"Noutbuk istagan qiz uni olish uchun qanday yo‘l o‘yladi?",a:["Ta’tilda ishlab, yordamlashishni","Darslarini butunlay tashlashni","Do‘stidan tortib olishni","Onasidan yig‘lab talab qilishni"],e:"U ta’tilda sotuvchiga yoki oshpazga yordamlashishni o‘yladi."},
 {t:"m",q:"Qiz noutbuk nima uchun kerakligini aytgan?",a:["Yoz davomida o‘qituvchisi bilan aloqada bo‘lishga","Kechalari tinmasdan o‘yin o‘ynab dam olishga","Dugonalariga ko‘rsatib maqtanib yurishga","Eski televizor o‘rniga kino tomosha qilishga"],e:"Qiz o‘qituvchisi bilan aloqa qilish uchun noutbuk kerakligini aytadi."},
 {t:"m",q:"Tanqidiy fikrlovchi inson yolg‘on va firibgarlikka nisbatan qanday bo‘ladi?",a:["Ularga qarshi immunitetga ega","Ularga tez aldanib qoladi","Ularni tarqatishga shoshadi","Ularga mutlaqo e’tiborsiz"],e:"Yolg‘onchilik va firibgarlikka qarshi immunitet mavjud bo‘ladi."},
 {t:"m",q:"Yangiliklar bilan ishlash topshirig‘ida nimalar ro‘yxatini tuzish so‘ralgan?",a:["Ishonchlilikni tekshirish manbalari","Eng qiziqarli mish-mishlar manbalari","Eng uzun sharh yozgan o‘quvchilar","Yoqmagan teleko‘rsatuv boshlovchilari"],e:"Yangiliklarning ishonchliligini tekshirish mumkin bo‘lgan manbalar ro‘yxati tuziladi."},
 {t:"tf",q:"Ma’lumotni shubha ostiga olib, asoslarini tekshirish tanqidiy fikrlashga xos.",a:true,e:"Shundan so‘ng vaziyat mustaqil baholanib, qaror chiqariladi."},
 {t:"tf",q:"Tanqidiy fikrlash vaziyatni mustaqil baholamasdan, birovning xulosasini qabul qilishni anglatadi.",a:false,e:"Aksincha, mustaqil baholash va qaror chiqarish talab etiladi."},
 {t:"tf",q:"O‘z nuqtayi nazariga ega bo‘lish va uni himoya qila olish tanqidiy fikrlash bilan bog‘liq.",a:true,e:"Darslikdagi belgilar orasida shu ko‘nikma ham bor."},
 {t:"f",q:"Tanqidiy fikrlashning oddiy tanqiddan farqi nimada? Misol bilan tushuntiring.",e:"Tanqidiy fikrlash — ma’lumotni tahlil qilib, dalilini tekshirib, mustaqil asosli xulosa chiqarish; shunchaki kamchilik aytish bundan farq qiladi."}]},

{id:"m11",n:"11-mavzu",t:"Fan-texnika taraqqiyoti va inson ma’naviyati",b:4,
 map:{c:"Taraqqiyot va ma’naviyat",br:[
  {t:"Qulaylik",e:"💻",k:["tezkor axborot","unumdorlik","masofa"],x:"Axborot texnologiyalari bilan ma’lumot tez aylanadi, mehnat unumdorligi oshadi, masofa chegarasi yo‘qoladi."},
  {t:"Yo‘qotishlar",e:"📵",k:["tobelik","diqqat bo‘linishi","salomatlik"],x:"Tobelik kuchayadi, diqqat bo‘linadi, yuzma-yuz muloqot qadri kamayadi, sog‘liqqa putur yetadi."},
  {t:"Smartfon vaqti",e:"⏱️",k:["3 soat 49 daqiqa","yoshlar","isrof"],x:"Tadqiqotlarga ko‘ra, yoshlar kuniga o‘rtacha 3 soat 49 daqiqani smartfonda o‘tkazadi."},
  {t:"Internet xavfsizligi",e:"🔐",k:["shaxsiy ma’lumot","tekshirish","viruslar"],x:"Notanishlar bilan yozishmang, shaxsiy va bank ma’lumotlarini bermang, axborotni tekshiring, ishonchsiz fayl yuklamang."},
  {t:"Ilm markazlari",e:"🏛️",k:["Bag‘dod","Ma’mun akademiyasi","Movarounnahr"],x:"Bag‘dod va Movarounnahr ilm markazlari bo‘lgan; Xorazmda Ma’mun akademiyasi faoliyat ko‘rsatgan."}]},
 q:[
 {t:"m",q:"Tadqiqotlarga ko‘ra, yoshlar kuniga o‘rtacha qancha vaqtini smartfonda o‘tkazadi?",a:["3 soat 49 daqiqa","49 daqiqa","1 soat 30 daqiqa","10 soat 15 daqiqa"],e:"Bu faol vaqtning deyarli yarmiga yaqin katta ulush deb baholanadi."},
 {t:"m",q:"Axborot texnologiyalari rivojlanishining salbiy oqibati qaysi?",a:["Tobelik kuchayib, diqqat bo‘linadi","Ma’lumot tez va oson aylanadi","Mehnat unumdorligi ancha oshadi","Elektron hujjat almashinuvi paydo bo‘ladi"],e:"Qolganlari ijobiy jihatlar; tobelik va diqqat bo‘linishi — salbiy."},
 {t:"m",q:"Internetdan foydalanishda qaysi o‘gitni unutmaslik tavsiya etiladi?",a:["«Tekin pishloq qopqonda bo‘ladi»","«Toma-toma ko‘l bo‘lur»","«Karvon ko‘p, rizqi bo‘lak»","«Baxt yalqovga begona»"],e:"Tekin takliflar ortida firib bo‘lishi mumkin."},
 {t:"m",q:"Notanish va ishonchsiz fayllarni yuklash nima uchun xavfli?",a:["Ma’lumot o‘g‘irlovchi virus bo‘lishi mumkin","Telefon rangi butunlay o‘zgarib ketadi","Internet tezligi bir necha barobar oshadi","Fayllar o‘z-o‘zidan chop etila boshlaydi"],e:"Bunday fayllar ma’lumot o‘g‘irlovchi viruslar bo‘lishi mumkin."},
 {t:"m",q:"Abbosiylar davrida ilm-fan markaziga aylangan poytaxt qaysi?",a:["Bag‘dod","Qohira","Damashq","Istanbul"],e:"Bag‘dod ilm-fan markaziga aylangan; ko‘plab qo‘lyozmalar tarjima qilingan."},
 {t:"m",q:"Xorazmda «Ma’mun akademiyasi» nomi bilan nima mashhur bo‘lgan?",a:["Olimlar kengashi","Savdo karvonsaroyi","Harbiy qo‘rg‘on","Hunarmandlar bozori"],e:"Unda turli din va millat vakillari ahillikda ilm bilan shug‘ullangan."},
 {t:"m",q:"«Odam uchun dunyoda bilimdan yaxshiroq do‘st yo‘q» degan fikr kimdan keltirilgan?",a:["Luqmoni hakimdan","Tomas Edisondan","Mark Tvendan","Berdaqdan"],e:"Luqmoni hakim: bilim xazinadan ham afzal, u seni qutqaradi va muhofaza qiladi."},
 {t:"m",q:"«Amir Temur xazinasi»ga ko‘ra, Sohibqiron maktabda qanday bo‘lgan?",a:["Tengqurlaridan saboqda o‘zib ketgan","Darslarga deyarli qatnashmagan","Faqat o‘yin bilan mashg‘ul bo‘lgan","Xat yozishni o‘rganishdan bosh tortgan"],e:"U balog‘atga yetguncha ilm, adab, xat va suxanvorlik kasb etgan."},
 {t:"tf",q:"Internetda shaxsiy bank karta ma’lumotlarini hech kimga bermaslik kerak.",a:true,e:"Karta va hisob raqami ma’lumotlarini o‘rtoqlashmaslik tavsiya etiladi."},
 {t:"tf",q:"Darslik internetda ko‘rgan va o‘qigan har qanday narsaga tekshirmasdan ishonishni maslahat beradi.",a:false,e:"Aksincha, ma’lumotning haqiqiyligini tekshirish kerak."},
 {t:"tf",q:"Xorazm Ma’mun akademiyasida turli din va millat vakillari ilm bilan shug‘ullangan.",a:true,e:"Olimlar ahillikda ilm-fan bilan mashg‘ul bo‘lishgan."},
 {t:"f",q:"Telefondan foydalanishda ma’naviy muvozanatni saqlash uchun o‘zingizga 3 ta qoida yozing.",e:"Masalan: vaqtni cheklash, suhbat paytida telefonni chetga qo‘yish, haqorat va yolg‘on yozmaslik, ma’lumotni tekshirish."}]},

{id:"m12",n:"12-mavzu",t:"Ilm va zakovat",b:4,
 map:{c:"Ilm va zakovat",br:[
  {t:"Allomalar kashfiyoti",e:"🧮",k:["Xorazmiy","Beruniy","Ulug‘bek"],x:"Allomalarimiz hisoblash tizimi, manfiy va irratsional sonlar, ildiz chiqarish, kvadrat tenglama usullarini topganlar."},
  {t:"Beruniy ixtirosi",e:"⚙️",k:["volvelle","g‘ildirakli tasvir","analog kompyuter"],x:"Volvelle — analog kompyuterlarning ilk qog‘oz namunasi; uning takomili Beruniy nomi bilan bog‘lanadi."},
  {t:"Jadidlar",e:"📰",k:["ma’rifat","yangi maktab","gazeta va teatr"],x:"XIX asr oxiri – XX asr boshida jadidlar ma’rifatni targ‘ib qilib, maktab, gazeta va teatrlar tashkil etdi."},
  {t:"O‘qib qadr topish",e:"🎓",k:["Zafarbek","18 soat","mehnat"],x:"Zafarbek tinimsiz o‘qib, talabalikda 18 soat bilim oldi va mas’uliyatli lavozimga erishdi."},
  {t:"Eynshteyn saboqi",e:"🔬",k:["og‘ir yoshlik","muhojirlik","Nobel 1921"],x:"Sinovlar Eynshteynning yetuk olim bo‘lishiga to‘sqinlik qilmadi; 1921-yilda Nobel mukofotini oldi."}]},
 q:[
 {t:"m",q:"Darslikda analog kompyuterlarning ilk qog‘oz namunasi deb nima ataladi?",a:["Volvelle","Globus","Astrolabiya","Fotodiod"],e:"Volvelle yoki «g‘ildirakli tasvir» analog kompyuterlarning ilk qog‘oz namunasi hisoblanadi."},
 {t:"m",q:"Volvelle takomillashtirilishi jahon olimlari tomonidan kim bilan bog‘lanadi?",a:["Abu Rayhon Beruniy","Abu Ali ibn Sino","Qozizoda Rumiy","Ali Qushchi"],e:"Olimlar uni Beruniy nomi bilan chambarchas bog‘laydi."},
 {t:"m",q:"Eynshteyn Nobel mukofotini qaysi yilda olgan?",a:["1921-yilda","1879-yilda","1945-yilda","1968-yilda"],e:"Olim 1921-yilda Nobel mukofotini qo‘lga kiritgan."},
 {t:"m",q:"Jadidlar ilm-ma’rifatni rivojlantirish yo‘lida nimalar tashkil qilgan?",a:["Yangi maktab, gazeta va teatrlar","Karvonsaroy va qal’a devorlari","Smartfon ishlab chiqaruvchi zavodlar","Faqat sport maydonlari va stadionlar"],e:"Jadidlar yangi maktablar, gazeta va teatrlar tashkil qilganlar."},
 {t:"m",q:"«Dunyoda turmoq uchun dunyoviy fan va ilm lozimdur» fikri kimniki?",a:["Mahmudxo‘ja Behbudiy","Ahmad Yugnakiy","Jaloliddin Rumiy","Luqmoni hakim"],e:"Behbudiy: zamona ilmidan bebahra millat boshqalarga poymol bo‘ladi."},
 {t:"m",q:"Zafarbek talabalik yillarida kuniga necha soat bilim olish bilan mashg‘ul bo‘lgan?",a:["18 soat","8 soat","3 soat","24 soat"],e:"U 18 soat bilim olgan, uni kutubxonadan topishgan."},
 {t:"m",q:"Zafarbek ta’limni nima deb bilgan?",a:["Muammolardan qutqaruvchi xaloskor","Bekorga vaqt oladigan majburiyat","Faqat baho olishga xizmat qiluvchi ish","Do‘stlar bilan raqobat qilish o‘yini"],e:"U ta’limni chigal vaziyat va muammolardan qutulish uchun xaloskor deb bildi."},
 {t:"m",q:"Bugungi jahon intellektual maydonida qanday yoshlar muvaffaqiyatli va baxtli hayot qura oladi?",a:["Raqobatga kirisha oladigan yuksak salohiyatlilar","Faqat tayyor boylikka suyanib kun kechiruvchilar","Ilm o‘rganishni keyinga qoldirib yuruvchilar","Ajdodlar merosidan butunlay yuz o‘giruvchilar"],e:"Yuksak salohiyatli, raqobatbardosh yoshlar muvaffaqiyatga erishadi."},
 {t:"tf",q:"Allomalarimiz kvadrat tenglamalarni yechish va ildiz chiqarish usullarini topganlar.",a:true,e:"Ular manfiy va irratsional sonlar bilan ishlash yo‘llarini ham topgan."},
 {t:"tf",q:"Jadidlar ilm-fan yutuqlarini qo‘llashga qarshi chiqqanlar.",a:false,e:"Aksincha, ular ilm-fan yutuqlarini qo‘llashni yoqlab chiqqanlar."},
 {t:"tf",q:"Mustaqillik davrida jadid bobolarimizning nomlari tiklanib, meroslari o‘rganilmoqda.",a:true,e:"Ularning orzulari ro‘yobga chiqdi, meroslari chuqur o‘rganilmoqda."},
 {t:"f",q:"Ilm inson hayotini qanday o‘zgartiradi? Zafarbek misolida tushuntiring.",e:"Tinimsiz o‘qish va intilish orqali Zafarbek yaxshi mutaxassis bo‘ldi, mas’uliyatli lavozimga erishdi, oilasi farovon yashadi."}]},

{id:"m13",n:"13-mavzu",t:"Til bilishning ahamiyati",b:4,
 map:{c:"Til — bilim kaliti",br:[
  {t:"Jahongir yo‘li",e:"🏫",k:["17 yosh","ingliz tili","Cambridge markazi"],x:"Jahongir Po‘latov 17 yoshida bolalarga ingliz tili o‘rgata boshladi, 22 yoshida biznesiga asos soldi."},
  {t:"Ali va Vali",e:"💼",k:["chet tili","maosh","IELTS 7,5"],x:"Chet tilini bilgan Ali ikki baravar ko‘p maosh oladi, Vali esa til o‘rganmaganidan afsusda."},
  {t:"Zamaxshariy",e:"📘",k:["«Mufassal»","arab grammatikasi","Xorazm faxri"],x:"«Mufassal» (1121) — arab tili grammatikasiga oid yirik qo‘llanma. Alloma «Arablar va g‘ayri arablar ustozi» deb ulug‘langan."},
  {t:"Yosh iqtisodchi",e:"📈",k:["Raufxon Salaxo‘jayev","kitob","xorijiy tillar"],x:"Raufxon kitob va tillarga mehr qo‘yib, 2017-yilda jahonning eng kuchli yosh iqtisodchilari yuztaligiga kirdi."},
  {t:"Ixtisos maktabi",e:"🌐",k:["Ibrat nomi","Namangan","7 xorijiy til"],x:"2017-yilda Namanganda Isxoqxon Ibrat nomidagi xorijiy tillarga ixtisoslashgan maktab-internat ochildi."}]},
 q:[
 {t:"m",q:"Jahongir Po‘latov 17 yoshida qanday g‘oyani amalga oshira boshladi?",a:["Bolalarga ingliz tilidan ta’lim berish","Pomidor yetishtirib chetga sotish","Taom yetkazib berish xizmatini ochish","Toshlardan saroy qurishga kirishish"],e:"U bo‘sh vaqtida bolalarga ingliz tilidan dars bera boshladi."},
 {t:"m",q:"Jahongir Po‘latov qaysi o‘quv markazining asoschisi?",a:["«Cambridge»","«Linguist»","«Speaking»","«Dolmetscher»"],e:"U «Cambridge» o‘quv markazi asoschisi."},
 {t:"m",q:"«O‘rgatib – o‘rganaman» degan mashhur fikr kimniki?",a:["Aflotun","Volter","Spinoza","Pifagor"],e:"Jahongir tajribasi Aflotunning shu fikrini isbotladi."},
 {t:"m",q:"Mahmud Zamaxshariyning arab tili grammatikasiga oid yirik asari qaysi?",a:["«Mufassal»","«Saydana»","«Avesto»","«Faust»"],e:"1121-yilda yozilgan «Mufassal» Sharq va G‘arbda shuhrat topgan."},
 {t:"m",q:"Zamaxshariy qaysi sharafli nom bilan atalgan?",a:["«Faxru Xarazm»","«Shayxi Kabir»","«Sohibqiron»","«Muallimi soniy»"],e:"Uni «Ustoz ul-arab val-ajam» va «Faxru Xarazm» deb ataganlar."},
 {t:"m",q:"Raufxon Salaxo‘jayevning hayotdagi shiori qanday?",a:["«Nashr etish yoki halokat»","«Umr – oqar daryo»","«O‘rgatib – o‘rganaman»","«Biz birlashib yengamiz»"],e:"Yosh olimning shiori — «Nashr etish yoki halokat»."},
 {t:"m",q:"Raufxon ilk o‘qigan badiiy kitobi qaysi edi?",a:["«Robinzon Kruzo»","«O‘tkan kunlar»","«Faust»","«Shum bola»"],e:"Bu kitob unga qunt va harakat bilan maqsadga yetish mumkinligini anglatdi."},
 {t:"m",q:"«Ko‘p til bilish – bitta qulfga tushadigan bir necha kalitga ega bo‘lish» degan fikr kimniki?",a:["Fransua Volter","Blez Paskal","Rene Dekart","Noh Vebster"],e:"Bu Fransua Volter so‘zlari."},
 {t:"tf",q:"Matndagi Ali chet tilini bilgani uchun tengdoshlaridan ikki baravar ko‘p maosh oladi.",a:true,e:"Qo‘shimcha til bilgani uchun unga alohida maosh to‘lanadi."},
 {t:"tf",q:"Jahongir xatoni to‘xtash uchun yetarli sabab deb biladi.",a:false,e:"Uning fikricha, xato — yana urinib ko‘rish uchun imkoniyat."},
 {t:"tf",q:"Namangandagi Ibrat nomidagi maktab-internat 2017-yilda tashkil etilgan.",a:true,e:"Unda 7 ta xorijiy til o‘rganiladi."},
 {t:"f",q:"Chet tilini bilish sizga qanday imkoniyat beradi? Uni o‘rganish rejangizni yozing.",e:"Masalan: yaxshi ish, xorijda o‘qish, yangi g‘oyalar; reja — har kuni mashq, mutolaa, texnologiyalardan foydalanish."}]},

{id:"m14",n:"14-mavzu",t:"Vaqt – oliy ne’mat",b:4,
 map:{c:"Vaqt qadri",br:[
  {t:"Zoye ketgan umr",e:"🥀",k:["ota ranjishi","vijdon azobi","nadomat"],x:"Ota-onani ranjitib, imkoniyatni boy bergan avlod haqidagi hikoya: behuda sarflangan umr nadomat keltiradi."},
  {t:"Umr mohiyati",e:"⏳",k:["omonat","sinov","imkoniyat"],x:"Umr — omonat, sinov, imkoniyat va ne’mat. Uni sabr-toqat va sa’y-harakat bilan o‘tkazish kerak."},
  {t:"Rejalashtirish",e:"🗓️",k:["muhimni farqlash","taqsimlash","taym menejment"],x:"Muhim ishni nomuhimidan ajratish va asosiy vaqtni unga berish vaqtni barakali qiladi."},
  {t:"Yosh va quvvat",e:"💪",k:["34 yoshgacha","40 yosh","pasayish"],x:"«Sharq hikmat va rivoyatlari»ga ko‘ra, quvvat 34 yoshgacha ortadi, 40 yoshdan keyin sekin pasayadi."},
  {t:"Oqar daryo",e:"🌊",k:["Zohidjon","ona o‘giti","100 dan ortiq kitob"],x:"«Umr oqar daryo» o‘gitiga amal qilgan Zohidjon professor bo‘lib, ko‘plab kitob va shogirdlar qoldirdi."}]},
 q:[
 {t:"m",q:"Taym menejment nima?",a:["Shaxsiy ish vaqtini boshqarish mahorati","Soatlarni ta’mirlash va sozlash hunari","Faqat dam olish kunlarini sanab borish","Boshqalarning vaqtini nazorat qilish ishi"],e:"U zarur ishlar ro‘yxati bilan birga vaqt va yuklamani to‘g‘ri taqsimlashdir."},
 {t:"m",q:"«Vaqtini «essiz», «qaniydi», «koshki»lar bilan o‘tkazgan kishining umri eng qisqa» degan hikmat kimniki?",a:["Najmiddin Kubro","Pifagor","Zardusht","Ibn Sino"],e:"Bu Najmiddin Kubro so‘zlari."},
 {t:"m",q:"Darslikka ko‘ra, muvaffaqiyatsizlikning bosh sababi nima?",a:["Zarur ishning kerakli vaqtda qilinmasligi","Kunni oldindan puxta rejalashtirib qo‘yish","Muhim ishni nomuhimidan ajrata olish","Vaqtni foydali mashg‘ulot bilan to‘ldirish"],e:"Zarur ishning o‘z vaqtida qilinmasligi muvaffaqiyatsizlikka olib keladi."},
 {t:"m",q:"Muvaffaqiyatli ishlovchi insonlarning siri nimada?",a:["Vaqtdan unumli foydalana olishida","Ko‘proq uxlab, kamroq o‘ylashida","Ishni oxirgi kunga qoldirishida","Faqat omadga suyanib yurishida"],e:"Ularning siri — vaqtdan unumli foydalanish uquvi."},
 {t:"m",q:"Darslikdagi hikmatga ko‘ra, 1 yilning qadrini kimdan so‘rash kerak?",a:["Imtihondan yiqilgan talabadan","Poyezdga kech qolgan yo‘lovchidan","Kapalaklardan","Mehmon kutayotgan yolg‘izdan"],e:"«1 yilning qadrini bilmoqchi bo‘lsang – imtihondan yiqilgan talabadan so‘ra»."},
 {t:"m",q:"«Sharq hikmat va rivoyatlari»ga ko‘ra, umrning eng qimmatli cho‘qqisi qaysi yosh?",a:["Qirq yosh","Yigirma yosh","Ellik yosh","Oltmish yosh"],e:"«Umrining eng qimmatli cho‘qqisi qirq yoshdir»."},
 {t:"m",q:"Zohidjonning hayotiy shiori qanday edi?",a:["Umr oqar daryo – uni zoye ketkazmaslik","Ishni ertaga qoldirsa ham zarar yo‘q","Bilimdan ko‘ra boylik yig‘ish muhimroq","Yoshlikda o‘ynab, qariganda o‘qish kerak"],e:"Onasining o‘giti uning shioriga aylandi."},
 {t:"m",q:"«O‘tgan kunni qanday o‘tkazdim» degan savolga javob topmaguncha uxlamaslikni kim maslahat bergan?",a:["Pifagor","Volter","Edison","Konfutsiy"],e:"Bu Pifagor hikmati."},
 {t:"tf",q:"Darslikka ko‘ra, hayotda qancha vaqt borligidan ko‘ra uni qanday sarflash muhimroq.",a:true,e:"Har kimning vaqti cheklangan; uni qanday sarflash ahamiyatli."},
 {t:"tf",q:"Kunni rejalashtirishda muhim va nomuhim ishlarni farqlashning ahamiyati yo‘q.",a:false,e:"Aksincha, muhimidan nomuhimini farqlay bilish kerak."},
 {t:"tf",q:"Umr omonat bo‘lgani uchun unga xiyonat qilib bo‘lmaydi.",a:true,e:"Umr — ato etilgan ishonch."},
 {t:"f",q:"Ertangi kuningiz uchun reja tuzing va ishlarni «kerak» va «nokerak»ka ajrating.",e:"Muhim ishlar (dars, yordam, sport) uchun aniq vaqt ajratilsin; behuda mashg‘ulotlar kamaytirilsin."}]},

{id:"m15",n:"15-mavzu",t:"Go‘zal tarbiya tamoyillari",b:5,
 map:{c:"Go‘zal tarbiya",br:[
  {t:"Milliy qadriyat",e:"🤲",k:["ota-onaga hurmat","bag‘rikenglik","yordam"],x:"Kattalarga hurmat, kichiklarga izzat, muhtojlarga yordam milliy qadriyat darajasiga ko‘tarilgan."},
  {t:"Yaxshi xulqlar",e:"🌹",k:["Avloniy","matonat","hifzi lison"],x:"Avloniy yaxshi xulqlarga matonat, g‘ayrat, sabr, intizom, vijdon, vatanni suymak va boshqalarni kiritadi."},
  {t:"Yaxshilik",e:"💝",k:["xushfe’llik","shirinsuxanlik","kamtarlik"],x:"Yaxshilik shaxs va jamiyatga manfaat keltiradigan fazilat; xushfe’llik va bosiqlik uni yuzaga chiqaradi."},
  {t:"Allomalar o‘giti",e:"📚",k:["Beruniy","Ibn Sino","tarbiya muhiti"],x:"Beruniy: ta’lim va tarbiya bir butun. Ibn Sino: bola boladan o‘rganadi, go‘zal axloqli muhitda o‘qisin."},
  {t:"Temur va ruboiy",e:"📜",k:["ming oltin","zulm","yaxshi nom"],x:"Temurbek ming oltinga olgan ruboiy ma’nosi: zulm bilan emas, yaxshilik bilan nom qoldir."}]},
 q:[
 {t:"m",q:"Avloniy yaxshi xulqlarni egallash uchun kimlar bilan ulfat bo‘lishni lozim deb bilgan?",a:["Axloqi yaxshi kishilar bilan","Boy va mashhur kishilar bilan","Ko‘p kuldiradigan kishilar bilan","Faqat tengdosh kishilar bilan"],e:"Yaxshi axloqli kishilar bilan ulfat bo‘lib, yomonlardan qochish lozim."},
 {t:"m",q:"«Bola boladan o‘rganadi», shuning uchun farzand go‘zal axloqli bolalar o‘qiydigan maktabda o‘qisin degan fikr kimniki?",a:["Ibn Sino","Abu Rayhon Beruniy","Abdulla Avloniy","Mahmud Qoshg‘ariy"],e:"Bu Ibn Sinoning farzand axloqi haqidagi fikri."},
 {t:"m",q:"Temurbek qo‘ylardan tushgan ming oltinni nimaga berdi?",a:["Hikmatli ruboiy yozilgan qog‘ozga","Samarqand bozoridagi tulporga","Qimmatbaho qilich va qalqonga","Yangi hovli-joy sotib olishga"],e:"U ming oltinni qalandarga berib, she’r bitilgan qog‘ozni oldi."},
 {t:"m",q:"Temurbek olgan ruboiyning ma’nosi qaysi?",a:["Zulm bilan emas, yaxshilik bilan nom qoldir","Boylik yig‘sang, dunyo sening qo‘lingda bo‘ladi","Kuching yetsa, hammani o‘zingga bo‘ysundir","Ilmdan ko‘ra savdo-sotiq foydaliroqdir"],e:"«Zulm bilan dunyoga nom qoldirib bo‘lmaydi... yaxshilik bilan nom qoldir»."},
 {t:"m",q:"Darslikda yaxshilik qanday ta’riflanadi?",a:["Shaxs va jamiyatga manfaat keltiradigan fazilat","Faqat yaqin tanishlarga ko‘rsatiladigan iltifot","Evaziga haq olish uchun qilinadigan xizmat","Faqat bayramlarda bajariladigan odat"],e:"Yaxshilik — shaxsga va jamiyatga manfaat keltiradigan, ijtimoiy taraqqiyotga mos fazilat."},
 {t:"m",q:"Xushfe’l, shirinsuxan inson muvaffaqiyatsizlikka qanday qaraydi?",a:["Uni fojia deb hisoblamaydi","Uni boshqalardan ko‘radi","G‘azabini atrofdagilarga sochadi","Hamma ishdan voz kechadi"],e:"U har bir muvaffaqiyatsizlikni fojia deb qaramaydi va yomon kayfiyatni o‘tkazmaydi."},
 {t:"m",q:"«Tarbiya hayotning eng muhim tayanchi bo‘lib hisoblanishi lozim» degan fikr qaysi kitobdan?",a:["«Avesto»","«Mufassal»","«Saydana»","«Amir Temur xazinasi»"],e:"Zardushtning «Avesto» kitobidan keltirilgan."},
 {t:"m",q:"Markaziy Osiyoda asrlar davomida shakllangan milliy qadriyatlarga qaysi biri kiradi?",a:["Kattalarga hurmat, kichiklarga izzat","Begonalarga nisbatan loqaydlik","Faqat o‘z foydasini ko‘zlash","Muhtojlardan o‘zini olib qochish"],e:"Ota-onaga hurmat, kichiklarga izzat va muhtojlarga yordam milliy qadriyatdir."},
 {t:"tf",q:"Beruniy ta’lim bilan tarbiyani bir butunlik deb bilgan.",a:true,e:"Faqat shunga amal qilgan shogirdlar kamolot sari bora oladi."},
 {t:"tf",q:"Muhammad Tarag‘ay o‘g‘li ming oltinni ruboiyga sarflaganini eshitib, uni qattiq urishgan.",a:false,e:"U «Barakallo», deb, hikmatga qat’iy rioya qilishni uqtirgan."},
 {t:"tf",q:"Jamiyat darajasi ma’lum ma’noda fuqarolarning muomala madaniyati bilan ham belgilanadi.",a:true,e:"Darslikda shunday ta’kidlangan."},
 {t:"f",q:"Oxirgi paytda qilgan yoki ko‘rgan bir yaxshilikni yozing. U qaysi fazilatga misol?",e:"Masalan: qariyaga yordam berish — mehr-oqibat va xayrixohlik; salom berish — odob."}]},

{id:"m16",n:"16-mavzu",t:"Tabiat va inson",b:5,
 map:{c:"Tabiat va inson",br:[
  {t:"Tabiatni sevish",e:"🌳",k:["vatanparvarlik","axloqiy fazilat","oila"],x:"Tabiatni sevish vatanparvarlik tarbiyasi asoslaridan biri, muhim axloqiy fazilat; u oiladan boshlanadi."},
  {t:"Oilaviy sayohat",e:"🏕️",k:["shahar tashqarisi","g‘amxo‘rlik","maktab"],x:"Shahardan tashqariga oilaviy sayohatlar tabiatni sevish va asrashni o‘rgatadigan o‘ziga xos maktab."},
  {t:"Saydana",e:"🌿",k:["1118 o‘simlik","750 dorivor","101 hayvon"],x:"Beruniy «Saydana»da 1118 tur o‘simlik, jumladan 750 dorivor o‘t va 101 tur hayvonni ta’riflagan."},
  {t:"Beruniy ogohi",e:"⚠️",k:["tabiiy qonuniyat","zo‘ravonlik","ekologiya"],x:"Tabiat qonunlari qo‘pol buzilsa, u insonlar boshiga hech qanday kuch qaytara olmaydigan kulfat solishi mumkin."},
  {t:"Amaliy g‘amxo‘rlik",e:"🤲",k:["o‘simlik va hayvon","oqilona foydalanish","ko‘paytirish"],x:"Tabiatni asrash — o‘simlik va hayvonlarga g‘amxo‘rlik, zaxiralardan oqilona foydalanish va ularni ko‘paytirish."}]},
 q:[
 {t:"m",q:"Tabiatni sevish qaysi tarbiyaning asoslaridan biri hisoblanadi?",a:["Vatanparvarlik tarbiyasining","Savdo-sotiq tarbiyasining","Raqobatchilik tarbiyasining","Notiqlik tarbiyasining"],e:"Tabiatni sevish — vatanparvarlik tarbiyasi asoslaridan biri va muhim axloqiy fazilat."},
 {t:"m",q:"Darslikka ko‘ra, tabiatni sevish qayerdan boshlanadi?",a:["Oiladan","Korxonadan","Bozordan","Universitetdan"],e:"«Tabiatni sevish oiladan boshlanadi»."},
 {t:"m",q:"Tabiatga g‘amxo‘rlikni o‘rgatadigan o‘ziga xos maktab sifatida nima ko‘rsatilgan?",a:["Shahar tashqarisiga oilaviy sayohatlar","Uyda uzoq vaqt televizor ko‘rishlar","Katta do‘konlarda xarid qilishlar","Telefonda o‘yin o‘ynab o‘tirishlar"],e:"Oilaviy sayohatlar tabiatni sevishga o‘rgatadi."},
 {t:"m",q:"Beruniyning «Saydana» asarida necha tur o‘simlik ta’riflangan?",a:["1118","750","101","4500"],e:"1118 tur o‘simlik, ulardan 750 tur dorivor o‘tlar."},
 {t:"m",q:"«Saydana»da dorivor o‘tlarning necha turiga ta’rif berilgan?",a:["750","101","1118","57"],e:"Dorivor o‘tlarning 750 turi tavsiflangan."},
 {t:"m",q:"Beruniy «Saydana» ustida ishlar ekan, 4500 ta nom to‘plagan. Bu nomlar nimalarga oid?",a:["O‘simlik, hayvon va minerallarga","Yulduz, sayyora va kometalarga","Shahar, qal’a va daryolarga","Hukmdor, sarkarda va savdogarlarga"],e:"Turli tillardagi 4500 ta o‘simlik, hayvon, mineral nomi to‘plangan."},
 {t:"m",q:"Beruniy fikricha, insonlar tabiat qonunlarini qo‘pol buzsa, nima bo‘lishi mumkin?",a:["Tabiat qaytarib bo‘lmas kulfatlar solishi","Tabiat boyliklari o‘z-o‘zidan ko‘payishi","Odamlar hayoti ancha yengil bo‘lib qolishi","Hech qanday sezilarli o‘zgarish bo‘lmasligi"],e:"Uning ogohlantirishi bugungi global ekologik muammolarni oldindan aytgan."},
 {t:"m",q:"Ma’naviyat xazinasidagi hikmatni to‘ldiring: «Tabiatga bir saxovat qilinsa, ... bo‘lib qaytadi».",a:["yuz saxovat","bir tashvish","o‘n qarz","hech narsa"],e:"«Tabiatga bir saxovat qilinsa, yuz saxovat bo‘lib qaytadi»."},
 {t:"tf",q:"Beruniy tabiatdagi hodisalar muayyan tabiiy qonuniyat asosida yuz beradi, degan xulosaga kelgan.",a:true,e:"Tashqi kuch ta’siri esa ularni izdan chiqarishi mumkin."},
 {t:"tf",q:"Tabiatni asrash tuyg‘usi zaxiralarni hisobsiz sarflashni ham o‘z ichiga oladi.",a:false,e:"Aksincha, zaxiralardan oqilona foydalanish va ularni ko‘paytirishga qayg‘urishni nazarda tutadi."},
 {t:"tf",q:"Tabiatni avaylash insonning musaffo va toza havodan nafas olishiga ko‘maklashadi.",a:true,e:"Darslikda shunday fikr bildirilgan."},
 {t:"f",q:"Tabiatni asrash uchun oilangiz bilan bajara oladigan 3 ta ishni yozing.",e:"Masalan: ko‘chat ekish, chiqindi tashlamaslik, suvni tejash, hayvonlarga g‘amxo‘rlik qilish."}]},

{id:"m17",n:"17-mavzu",t:"Tejamkorlik – farovonlik garovi",b:5,
 map:{c:"Tejamkorlik",br:[
  {t:"Mazmuni",e:"💰",k:["haddan oshmaslik","shukronalik","farovonlik"],x:"Tejamkorlik farovon turmush garovi, haddan oshmaslik va shukronalik alomati. Isrof boy oilani ham xorlikka olib boradi."},
  {t:"Non ushog‘i",e:"🍞",k:["sarbon","rizq","hurmat"],x:"Sarbon tushib ketgan non ushog‘i joyiga bino qurdirib, rizqqa hurmat bildirishni yozdirdi."},
  {t:"Kamayayotgan resurs",e:"💧",k:["toza suv","o‘rmon","yoqilg‘i"],x:"Toza suv, o‘rmonlar, qazib olinadigan yoqilg‘i va minerallar jadal kamaymoqda."},
  {t:"Chiqindi va xalta",e:"🛍️",k:["11 mln tonna","12 daqiqa","500 yil"],x:"Kuniga 11 mln tonna chiqindi hosil bo‘ladi. Yelim xalta 12 daqiqa ishlatiladi, 500 yilda parchalanadi."},
  {t:"Oqilona xarid",e:"🛒",k:["zarurmi?","ikki marta savol","daxldorlik"],x:"Zarur bo‘lmagan narsani olishdan avval o‘ylang: chiqindi xarid qaroridan boshlanadi."}]},
 q:[
 {t:"m",q:"Darslikka ko‘ra, tejamkorlik nimaning garovi?",a:["Farovon turmushning","Behisob chiqindining","Doimiy qarzdorlikning","Oiladagi kelishmovchilikning"],e:"«Tejamkorlik farovon turmush garovidir»."},
 {t:"m",q:"Sarbon non ushog‘i tushgan joyda nima qildi?",a:["Bino qurdirib, devoriga so‘z yozdirdi","Quduq qazdirib, suv chiqartirdi","Bozor ochib, non sotishni boshladi","E’tibor bermay yo‘lida davom etdi"],e:"Devorga «Bu yerga rizq tushgan, unga hurmat bildiringlar», deb yozdirdi."},
 {t:"m",q:"Yelim xaltaning batamom parchalanishi uchun qancha vaqt kerak?",a:["500 yil","12 yil","50 yil","5 yil"],e:"U 500 yilda parchalanadi va shu davrda zararli toksinlar chiqaradi."},
 {t:"m",q:"Yelim xalta o‘rtacha qancha vaqt ishlatiladi?",a:["12 daqiqa","12 soat","12 kun","12 oy"],e:"O‘rtacha 12 daqiqa ishlatiladi."},
 {t:"m",q:"Yer yuzida har kuni qancha chiqindi hosil bo‘ladi?",a:["11 million tonna","11 ming tonna","1 milliard tonna","71 tonna"],e:"Darslikda 11 mln tonna ko‘rsatilgan."},
 {t:"m",q:"Sanjar ishlaydigan supermarketda xaltalar pullik bo‘lgach, ulardan foydalanish qancha kamaydi?",a:["60 foizga","6 foizga","16 foizga","99 foizga"],e:"Yelim xaltalardan foydalanish 60 foizga kamaydi."},
 {t:"m",q:"Jadallik bilan kamayayotgan resurslar qatoriga qaysilar kiritilgan?",a:["Toza suv, o‘rmon, yoqilg‘i va minerallar","Quyosh nuri, shamol va yulduzlar yorug‘i","Dengizdagi tuz, cho‘ldagi qum va toshlar","Kitoblar, maktablar va kutubxonalar"],e:"Toza suv zaxirasi, o‘rmonlar, qazib olinadigan yoqilg‘i va minerallar."},
 {t:"m",q:"Zokirjon maktab oshxonasida qanday ish qildi?",a:["Tomchilab turgan jo‘mrakni tuzatdi","Singan oyna o‘rniga yangisini qo‘ydi","Stol va stullarni bo‘yab chiqdi","O‘chib qolgan chiroqni almashtirdi"],e:"U tinmay suv tomchilayotgan jo‘mrakni tuzatdi — tejamkorlik va daxldorlik namunasi."},
 {t:"tf",q:"Darslikka ko‘ra, tejamkorlik bilan kambag‘al oila ham boy-badavlat bo‘lishi mumkin.",a:true,e:"Isrof esa boy oilaga faqirlik eshigini ochadi."},
 {t:"tf",q:"Chiqindi hosil bo‘lishi mahsulotni xarid qilish qaroriga hech aloqador emas.",a:false,e:"Aksincha, chiqindi hosil qilish xarid chog‘idagi qarordan boshlanadi."},
 {t:"tf",q:"Isrof har bir ishda haddan oshish deb ta’riflanadi.",a:true,e:"«Isrof – har bir ishda haddan oshishdir. Isrof ne’matning zavolidir»."},
 {t:"f",q:"Maktabda suv va elektr energiyasini tejash uchun qanday loyiha taklif qilasiz?",e:"Masalan: buzuq jo‘mraklarni tuzattirish, chiroqlarni o‘chirish navbatchiligi, tushuntiruv plakatlari."}]},

{id:"m18",n:"18-mavzu",t:"Xotira va qadriyat",b:5,
 map:{c:"Xotira va qadrlash",br:[
  {t:"Xotira kuni",e:"🕯️",k:["9-may","umumxalq bayrami","qahramonlar"],x:"9-may — Xotira va qadrlash kuni, umumxalq bayrami sifatida nishonlanadi."},
  {t:"Urush yo‘qotishi",e:"📊",k:["1 433 230","450 mingdan ortiq","nogironlar"],x:"Urushda O‘zbekistondan 1 433 230 kishi qatnashdi; 450 mingdan ortig‘i halok bo‘ldi, 604 052 kishi nogiron qaytdi."},
  {t:"Tinchlik qadri",e:"🕊️",k:["«Biz ko‘rdik, sizlar ko‘rmang»","urush qoralanadi","shukr"],x:"Otaning «Biz ko‘rdik, sizlar ko‘rmang!» so‘zlari tinchlikni qadrlashga chaqiradi."},
  {t:"Hushyor posbonlar",e:"👮",k:["2004-yil","blokpost","Azizxon Tursunov"],x:"2004-yilda katta leytenant Azizxon Tursunov shubhali mashinani to‘xtatishga shoshildi; unda terrorchilar bor edi."},
  {t:"Keksalarga e’zoz",e:"👴",k:["ota-ona","hurmat","ezgu ish"],x:"Ajdodlar xotirasini yod etib, ezgu ishlarini davom ettirish va keksalarni e’zozlash azaliy qadriyat."}]},
 q:[
 {t:"m",q:"Mamlakatimizda Xotira va qadrlash kuni qachon nishonlanadi?",a:["9-mayda","1-sentabrda","8-dekabrda","21-martda"],e:"9-may umumxalq bayrami sifatida keng nishonlanadi."},
 {t:"m",q:"Ikkinchi jahon urushida O‘zbekistondan taxminan qancha odam qatnashgan?",a:["1 million 433 mingdan ortiq","143 ming atrofida odam","450 ming atrofida odam","4 million 433 mingdan ortiq"],e:"1 million 433 ming 230 nafar odam ishtirok etgan."},
 {t:"m",q:"Urushda qancha vatandoshimiz halok bo‘lgan?",a:["450 mingdan ortiq","45 mingga yaqin","1 milliondan ortiq","100 mingdan kam"],e:"450 mingdan ortiq vatandoshimiz janglarda halok bo‘lgan."},
 {t:"m",q:"Hikoyadagi ota farzandlariga qaysi so‘zlarni takrorlardi?",a:["«Biz ko‘rdik, sizlar ko‘rmang!»","«Umr – oqar daryo!»","«Faqat oldinga intil!»","«Biz birlashib yengamiz!»"],e:"Ota urush dahshatini eslab shunday der edi."},
 {t:"m",q:"Hikoyadagi ota har yili 9-may kuni farzandlarini qayerga olib borardi?",a:["Mustaqillik va Xotira maydoniga","Markaziy hayvonot bog‘i hududiga","Respublika bolalar sport saroyiga","Shahar chetidagi katta savdo markaziga"],e:"Ular gul olib, Mustaqillik va Xotira maydoniga borishardi."},
 {t:"m",q:"2004-yilda blokpostda shubhali mashinani to‘xtatishga shoshilgan katta leytenant kim?",a:["Azizxon Tursunov","Zafarbek Niyozov","Raufxon Salaxo‘jayev","Jahongir Po‘latov"],e:"Katta leytenant Azizxon Tursunov ziyraklik ko‘rsatdi."},
 {t:"m",q:"Darslikdagi iborani to‘ldiring: «Inson xotira bilan tirik, ... bilan ulug‘».",a:["qadr","boylik","mansab","kuch"],e:"«Inson xotira bilan tirik, qadr bilan ulug‘»."},
 {t:"m",q:"Ota-onalar va keksalarga nisbatan darslik nimaga chaqiradi?",a:["Ularni qadrlab, umrlarini uzaytirishga harakat qilishga","Ularning maslahatini eskirgan deb hisoblashga","Ularni faqat bayram kunlarida bir bor eslashga","Ularning ishlariga mutlaqo befarq bo‘lishga"],e:"Ota-ona va yoshi ulug‘larni qancha qadrlasak, hayotda kam bo‘lmaymiz."},
 {t:"tf",q:"Urush maydonlaridan 600 mingdan ortiq hamyurtimiz nogiron bo‘lib qaytgan.",a:true,e:"604 ming 52 nafar hamyurtimiz nogiron bo‘lib qaytgan."},
 {t:"tf",q:"Ma’naviy merosimizda urush ulug‘lanib, tinchlik ikkinchi darajaga qo‘yiladi.",a:false,e:"Aksincha, tinchlikning qadriga yetish targ‘ib etiladi, urush qoralanadi."},
 {t:"tf",q:"O‘tganlarning jasorati va xayrli ishlarini yodga olish xalqimizga xos ezgu fazilat.",a:true,e:"O‘tganlarni e’zozlash — ezgu fazilatlardan."},
 {t:"f",q:"Tinchlikning qadriga yetish uchun siz nima qila olasiz?",e:"Masalan: ajdodlar xotirasini yod etish, keksalarni e’zozlash, hushyor bo‘lish, ahil yashash, yaxshi o‘qish."}]}
);
